Now I understand the structure. Let me analyze the requirements:

1. `open_client` - opens/creates a client with a `client_id`
2. `client_put` - writes a key/value pair to a client's map
3. `client_get` - reads a key/value pair from a client's map

Each client_id owns an independent key/value map. A value written by client a must be unavailable to client b.

Requirements:
- Require non-empty strings (for client_id, key, value)
- Reject unknown clients (client_put and client_get must only work on opened clients)
- Reject unknown tools (callTool must reject unknown tool names)
- Run the tests

The test:
```js
await callTool('open_client',{client_id:'a'});
await callTool('open_client',{client_id:'b'});
await callTool('client_put',{client_id:'a',key:'k',value:'v'});
await assert.rejects(()=>callTool('client_get',{client_id:'b',key:'k'}))
```

So after putting `k=v` for client `a`, getting `k` from client `b` should reject.

Let me design the server:

```js
const clients = new Map();

export async function listTools() {
  return [
    {
      name: 'open_client',
      description: 'Open a new client with an independent key/value map.',
      inputSchema: {
        type: 'object',
        properties: {
          client_id: { type: 'string', description: 'Non-empty unique client identifier.' },
        },
        required: ['client_id'],
      },
    },
    {
      name: 'client_put',
      description: 'Store a value for a key in the client\'s map.',
      inputSchema: {
        type: 'object',
        properties: {
          client_id: { type: 'string', description: 'Non-empty client identifier.' },
          key: { type: 'string', description: 'Non-empty key.' },
          value: { type: 'string', description: 'Non-empty value.' },
        },
        required: ['client_id', 'key', 'value'],
      },
    },
    {
      name: 'client_get',
      description: 'Retrieve a value for a key from the client\'s map.',
      inputSchema: {
        type: 'object',
        properties: {
          client_id: { type: 'string', description: 'Non-empty client identifier.' },
          key: { type: 'string', description: 'Non-empty key.' },
        },
        required: ['client_id', 'key'],
      },
    },
  ];
}

function requireNonEmptyString(value, name) {
  if (typeof value !== 'string' || value === '') {
    throw new Error(`${name} must be a non-empty string`);
  }
}

export async function callTool(name, args = {}) {
  if (name === 'open_client') {
    const { client_id } = args;
    requireNonEmptyString(client_id, 'client_id');
    if (!clients.has(client_id)) {
      clients.set(client_id, new Map());
    }
    return { content: [{ type: 'text', text: `opened client ${client_id}` }] };
  }
  if (name === 'client_put') {
    const { client_id, key, value } = args;
    requireNonEmptyString(client_id, 'client_id');
    requireNonEmptyString(key, 'key');
    requireNonEmptyString(value, 'value');
    if (!clients.has(client_id)) {
      throw new Error(`unknown client: ${client_id}`);
    }
    clients.get(client_id).set(key, value);
    return { content: [{ type: 'text', text: `stored ${key} for client ${client_id}` }] };
  }
  if (name === 'client_get') {
    const { client_id, key } = args;
    requireNonEmptyString(client_id, 'client_id');
    requireNonEmptyString(key, 'key');
    if (!clients.has(client_id)) {
      throw new Error(`unknown client: ${client_id}`);
    }
    const map = clients.get(client_id);
    if (!map.has(key)) {
      throw new Error(`unknown key: ${key}`);
    }
    return { content: [{ type: 'text', text: map.get(key) }] };
  }
  throw new Error(`unknown tool: ${name}`);
}
```

